-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> elem(t, ["int", "null"]), ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(elem(at(ts, 0), ["int", "text", "null"]), "TYPE_ERROR")
        at(ts, 0)
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> elem(t, ["bool", "null"]), ts), "TYPE_ERROR")
        "bool"
      elif elem(e.op, ["IS NULL", "IS NOT NULL"]) then
        "bool"
      elif e.op == "COALESCE" then
        let concrete = filter(\(t) -> t /= "null", ts)
        let common = if length(concrete) == 0 then "null" else at(concrete, 0)
        demand(all(\(t) -> t == common, concrete), "TYPE_ERROR")
        common
      else
        demand(
            (at(ts, 0) == at(ts, 1) || elem("null", ts))
              && (not(elem("bool", ts)) || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(elem(b.kind, ["bool", "null"]), "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier, nullable = at(t.columns, k).nullable || (i > 0 && at(q.left_joins, i - 1)) },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\(o) -> (alias_index(aliases, fst(o), 0), snd(o)), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- Command state is immutable. A handled Domain rejection returns the original
-- state, so base rows, reserved IDs, view caches and revision commit together.
import Json (..)
import Model (..)
import Parser (parse_sql)
import Binder (bind)
import Engine (optimize)
import Incremental (..)
import Data.List (..)
import Data.Map (..)
import Data.String (..)
import Data.Foldable (all, length)

pub fn success(value : Json) : Json =
  JObj([("ok", JBool(true)), ("result", value)])

pub fn failure(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

pub fn has_field(j : Json, key : String) : Bool =
  match j of
    JObj(xs) => length(filter(\(kv) -> fst(kv) == key, xs)) > 0
    _ => false

fn view_name(s : String) : Bool =
  byte_len(s) >= 1 && byte_len(s) <= 40
    && byte_at(s, 0) >= 97 && byte_at(s, 0) <= 122
    && all(\(i) -> let c = byte_at(s, i) in c >= 97 && c <= 122 || digit(c) || c == 45, range(0, byte_len(s)))

fn table_name(s : String) : Bool =
  byte_len(s) > 0 && letter(byte_at(s, 0))
    && all(\(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)), range(0, byte_len(s)))

fn validate_change(c : Json) : Unit =
  let op = text(getfield(c, "op"))
  demand(elem(op, ["insert", "update", "delete"]), "INVALID_COMMAND")
  fields(c, if op == "delete" then ["op", "table", "id"] else ["op", "table", "id", "row"])
  demand(table_name(text(getfield(c, "table"))), "INVALID_COMMAND")
  let id = getfield(c, "id")
  demand(value_type(id) == "int" && integer(id) >= 1 && integer(id) <= 2147483647, "INVALID_COMMAND")
  if op /= "delete" then
    let ignored = arr(getfield(c, "row"))
    ()

fn command_shape(c : Json) : Unit =
  let op = text(getfield(c, "op"))
  demand(elem(op, ["create", "read", "drop", "apply"]), "INVALID_COMMAND")
  if op == "apply" then
    fields(c, ["op", "changes"])
    let changes = arr(getfield(c, "changes"))
    demand(length(changes) >= 1 && length(changes) <= 200, "INVALID_COMMAND")
    for change in sof(changes) do
      validate_change(change)
  else
    fields(c, if op == "create" then ["op", "view", "sql", "optimize"] else ["op", "view"])
    demand(view_name(text(getfield(c, "view"))), "INVALID_COMMAND")
    if op == "create" then
      let ignored = text(getfield(c, "sql"))
      demand(value_type(getfield(c, "optimize")) == "bool", "INVALID_COMMAND")

fn shape_ok(c : Json) : Bool =
  handle command_shape(c) with
    never reject(_) => false
    return _ => true

fn validate_row(row : List(Json), cs : List(Column)) : Unit =
  demand(length(row) == length(cs), "INVALID_ROW")
  for i in srange(0, length(cs)) do
    let v = at(row, i)
    let c = at(cs, i)
    demand(value_type(v) == c.kind || is_null(v) && c.nullable, "INVALID_ROW")
    match v of
      JInt(n) => demand(n >= -1000000000 && n <= 1000000000, "INVALID_ROW")
      _ => ()

pub type State = State { database: Map(String, Base), views: Map(String, View), revision: Int }

fn revision(r : Int) : Json = JObj([("revision", JInt(r))])

fn require_base(name : String, db : Map(String, Base)) : Base =
  match map_lookup(name, db) of
    Some(b) => b
    None =>
      reject("UNKNOWN_TABLE")
      require_base(name, db)

fn require_view(name : String, vs : Map(String, View)) : View =
  match map_lookup(name, vs) of
    Some(v) => v
    None =>
      reject("UNKNOWN_VIEW")
      require_view(name, vs)

fn command(s : State, c : Json) : (State, Json) =
  demand(shape_ok(c), "INVALID_COMMAND")
  let op = text(getfield(c, "op"))
  if op == "apply" then
    var database := s.database
    var touched := map_empty
    for change in sof(arr(getfield(c, "changes"))) do
      let name = text(getfield(change, "table"))
      demand(map_member(name, database), "UNKNOWN_TABLE")
      let b = require_base(name, database)
      let action = text(getfield(change, "op"))
      let id = integer(getfield(change, "id"))
      let row = if action == "delete" then [] else arr(getfield(change, "row"))
      if action /= "delete" then validate_row(row, b.table.columns)
      if action == "insert" then
        demand(not(map_member(id, b.used)), "ROW_ID_USED")
        database := map_insert(name, Base { ..b, live = map_insert(id, LiveRow { position = b.next, row = row }, b.live), used = map_insert(id, true, b.used), next = b.next + 1 }, database)
      else
        demand(map_member(id, b.live), "UNKNOWN_ROW")
        if action == "delete" then
          database := map_insert(name, Base { ..b, live = map_delete(id, b.live) }, database)
        else
          let old = lookup(id, b.live, LiveRow { position = 0, row = [] })
          database := map_insert(name, Base { ..b, live = map_insert(id, LiveRow { ..old, row = row }, b.live) }, database)
      let ids = lookup(name, touched, [])
      touched := map_insert(name, if elem(id, ids) then ids else Cons(id, ids), touched)
    let committed = database
    let changed = touched
    let views = map_from_list(map(\(kv) -> (fst(kv), update_view(snd(kv), s.database, committed, changed)), map_to_list(s.views)))
    (State { database = committed, views = views, revision = s.revision + 1 }, revision(s.revision + 1))
  else
    let name = text(getfield(c, "view"))
    if op == "create" then
      demand(not(map_member(name, s.views)), "VIEW_EXISTS")
      let database = map(\(kv : (String, Base)) -> snd(kv).table, map_to_list(s.database))
      let plan = bind(parse_sql(text(getfield(c, "sql"))), database)
      let view = create_view(if truth(getfield(c, "optimize")) then optimize(plan) else plan, s.database)
      (State { ..s, views = map_insert(name, view, s.views) }, JObj([("view", JStr(name)), ("revision", JInt(s.revision))]))
    else
      demand(map_member(name, s.views), "UNKNOWN_VIEW")
      if op == "drop" then
        (State { ..s, views = map_delete(name, s.views) }, JObj([("dropped", JStr(name))]))
      else
        let v = require_view(name, s.views)
        (s, JObj([("revision", JInt(s.revision)), ("columns", getfield(v.result, "columns")), ("rows", getfield(v.result, "rows"))]))

fn attempt(s : State, c : Json) : (State, Json) =
  handle command(s, c) with
    never reject(code) => (s, failure(code))
    return pair => (fst(pair), success(snd(pair)))

pub fn commands(database : List(Table), cs : List(Json)) : Json =
  demand(length(cs) <= 2000, "INVALID_INPUT")
  var state := State { database = map_from_list(map(\(t) -> (t.name, base_table(t)), database)), views = map_empty, revision = 0 }
  var replies := []
  for c in sof(cs) do
    let next = attempt(state, c)
    state := fst(next)
    replies := Cons(snd(next), replies)
  success(JObj([("results", JArr(reverse(replies)))]))

-- Persistent bags are keyed by encounter-position lineage, never by SQL values.
-- A batch propagates final old/new rows once through each relational stage.
import Json (..)
import Model (..)
import Engine (..)
import Data.List (..)
import Data.Map (..)
import Data.String (pad_left)
import Data.Foldable (all, length)

pub type LiveRow = LiveRow { position: Int, row: List(Json) }
pub type Base = Base { table: Table, live: Map(Int, LiveRow), used: Map(Int, Bool), next: Int }
pub alias Rows = Map(String, List(Json))
alias Index = Map(String, Rows)

pub fn empty_rows() : Rows = map_empty

pub fn lookup(key : k, m : Map(k, v), fallback : v) : v given Ord(k) =
  match map_lookup(key, m) of
    Some(v) => v
    None => fallback

pub fn base_table(t : Table) : Base =
  var live := map_empty
  var used := map_empty
  var n := 1
  for r in sof(t.rows) do
    live := map_insert(n, LiveRow { position = n, row = r }, live)
    used := map_insert(n, true, used)
    n += 1
  Base { table = Table { ..t, rows = [] }, live = live, used = used, next = n }

fn position_key(n : Int) : String = pad_left(show_int(n), 10)

fn scan_row(p : Plan, source : Int, r : List(Json)) : Bool =
  let width = length(flatten(map(\(t) -> t.columns, take(source, p.tables))))
  let padded = append(replicate(width, JNull), r)
  all(\(e) -> truth(evaluate(e, padded, [])), at(p.filters, source))

fn initial_scan(p : Plan, source : Int, b : Base) : Rows =
  var rows := empty_rows()
  for pair in sof(map_to_list(b.live)) do
    let r = snd(pair)
    if scan_row(p, source, r.row) then
      rows := map_insert(position_key(r.position), r.row, rows)
  rows

fn changed_scan(p : Plan, source : Int, old : Base, new : Base, ids : List(Int), rows : Rows) : (Rows, List(String)) =
  var out := rows
  var changed := map_empty
  for id in sof(ids) do
    match map_lookup(id, old.live) of
      Some(r) =>
        let k = position_key(r.position)
        out := map_delete(k, out)
        changed := map_insert(k, true, changed)
      None => ()
    match map_lookup(id, new.live) of
      Some(r) =>
        let k = position_key(r.position)
        if scan_row(p, source, r.row) then
          out := map_insert(k, r.row, out)
        changed := map_insert(k, true, changed)
      None => ()
  (out, map(fst, map_to_list(changed)))

-- A usable equality conjunct restricts probes; arbitrary ON expressions use
-- one bucket and still evaluate only the affected left/right contributions.
fn equality(on : Expr, offset : Int) : (Int, Int) =
  if on.op == "AND" then
    let a = equality(at(on.args, 0), offset)
    if fst(a) >= 0 then a else equality(at(on.args, 1), offset)
  elif on.op == "=" then
    let a = at(on.args, 0)
    let b = at(on.args, 1)
    if a.op == "col" && b.op == "col" then
      if a.index < offset && b.index >= offset then
        (a.index, b.index - offset)
      elif b.index < offset && a.index >= offset then
        (b.index, a.index - offset)
      else (-1, -1)
    else (-1, -1)
  else (-1, -1)

fn bucket(row : List(Json), slot : Int) : String =
  if slot < 0 then "" else encode(at(row, slot))

fn index_add(index : Index, slot : Int, k : String, row : List(Json)) : Index =
  let b = bucket(row, slot)
  map_insert(b, map_insert(k, row, lookup(b, index, empty_rows())), index)

fn index_remove(index : Index, slot : Int, k : String, row : List(Json)) : Index =
  let b = bucket(row, slot)
  let rs = map_delete(k, lookup(b, index, empty_rows()))
  if map_height(rs) == 0 then map_delete(b, index) else map_insert(b, rs, index)

fn update_index(index : Index, slot : Int, old : Rows, new : Rows, changes : List(String)) : Index =
  var out := index
  for k in sof(changes) do
    match map_lookup(k, old) of
      Some(r) => out := index_remove(out, slot, k, r)
      None => ()
    match map_lookup(k, new) of
      Some(r) => out := index_add(out, slot, k, r)
      None => ()
  out

pub type Stage = Stage {
  left_slot: Int, right_slot: Int, left_index: Index, right_index: Index,
  children: Map(String, Rows), rows: Rows
}

fn empty_stage(on : Expr, offset : Int) : Stage =
  let slots = equality(on, offset)
  Stage { left_slot = fst(slots), right_slot = snd(slots), left_index = map_empty,
    right_index = map_empty, children = map_empty, rows = empty_rows() }

fn maintain_join(s : Stage, old_left : Rows, new_left : Rows, dl : List(String), old_right : Rows, new_right : Rows, dr : List(String), on : Expr, outer : Bool, width : Int) : (Stage, List(String)) =
  let li = update_index(s.left_index, s.left_slot, old_left, new_left, dl)
  let ri = update_index(s.right_index, s.right_slot, old_right, new_right, dr)
  var affected := map_from_list(map(\(k) -> (k, true), dl))
  -- Probe both old and new right keys, against final left rows. Changed left
  -- rows are already in affected, including deletions and key changes.
  for k in sof(dr) do
    for right in sof([old_right, new_right]) do
      match map_lookup(k, right) of
        Some(r) =>
          let candidates = lookup(bucket(r, s.right_slot), li, empty_rows())
          for pair in sof(map_to_list(candidates)) do
            affected := map_insert(fst(pair), true, affected)
        None => ()
  var children := s.children
  var out := s.rows
  var delta := map_empty
  for pair in sof(map_to_list(affected)) do
    let k = fst(pair)
    for old in sof(map_to_list(lookup(k, children, empty_rows()))) do
      out := map_delete(fst(old), out)
      delta := map_insert(fst(old), true, delta)
    children := map_delete(k, children)
    match map_lookup(k, new_left) of
      None => ()
      Some(l) =>
        var matches := empty_rows()
        let candidates = lookup(bucket(l, s.left_slot), ri, empty_rows())
        for right in sof(map_to_list(candidates)) do
          let row = append(l, snd(right))
          if truth(evaluate(on, row, [])) then
            matches := map_insert(concat(k, concat("/", fst(right))), row, matches)
        if outer && map_height(matches) == 0 then
          matches := map_insert(concat(k, concat("/", position_key(0))), append(l, replicate(width, JNull)), matches)
        for child in sof(map_to_list(matches)) do
          out := map_insert(fst(child), snd(child), out)
          delta := map_insert(fst(child), true, delta)
        children := map_insert(k, matches, children)
  (Stage { ..s, left_index = li, right_index = ri, children = children, rows = out }, map(fst, map_to_list(delta)))

-- Each aggregate occurrence has a private slot. Scalar evaluation remains the
-- checkpoint-one evaluator, with aggregate slots substituted by typed literals.
fn number_aggs(e : Expr, start : Int) : (Expr, List(Expr)) =
  if agg(e.op) then
    (Expr { ..e, index = start }, [e])
  else
    let pair = number_args(e.args, start)
    (Expr { ..e, args = fst(pair) }, snd(pair))

fn number_args(args : List(Expr), start : Int) : (List(Expr), List(Expr)) =
  match args of
    Nil => ([], [])
    Cons(a, rest) =>
      let next = number_aggs(a, start)
      let remaining = number_args(rest, start + length(snd(next)))
      (Cons(fst(next), fst(remaining)), append(snd(next), snd(remaining)))

fn prepare(p : Plan) : (Plan, List(Expr)) =
  var aggs := []
  var sels := []
  for item in sof(p.query.select) do
    let next = number_aggs(fst(item), length(aggs))
    sels := Cons((fst(next), snd(item)), sels)
    aggs := append(aggs, snd(next))
  let hav = number_aggs(p.query.having, length(aggs))
  (Plan { ..p, query = Query { ..p.query, select = reverse(sels), having = fst(hav) } }, append(aggs, snd(hav)))

pub type Acc = Acc { count: Int, total: Int, ints: Map(Int, Int), texts: Map(String, Int) }
fn empty_acc() : Acc = Acc { count = 0, total = 0, ints = map_empty, texts = map_empty }

fn counted(m : Map(k, Int), k : k, sign : Int) : Map(k, Int) given Ord(k) =
  let n = lookup(k, m, 0) + sign
  if n == 0 then map_delete(k, m) else map_insert(k, n, m)

fn accumulate(a : Acc, e : Expr, row : List(Json), sign : Int) : Acc =
  let v = if length(e.args) == 0 then JInt(1) else evaluate(at(e.args, 0), row, [])
  if is_null(v) then a
  else
    let n = Acc { ..a, count = a.count + sign }
    if e.op == "SUM" then Acc { ..n, total = a.total + sign * integer(v) }
    elif elem(e.op, ["MIN", "MAX"]) then
      match v of
        JInt(i) => Acc { ..n, ints = counted(a.ints, i, sign) }
        JStr(s) => Acc { ..n, texts = counted(a.texts, s, sign) }
        _ => n
    else n

fn extreme(m : Map(k, Int), minimum : Bool, fallback : k) : k =
  match m of
    Tip => fallback
    Bin(_, k, _, l, r) =>
      if minimum then
        if map_height(l) == 0 then k else extreme(l, minimum, fallback)
      else
        if map_height(r) == 0 then k else extreme(r, minimum, fallback)

fn acc_value(a : Acc, e : Expr) : Json =
  if e.op == "COUNT" then JInt(a.count)
  elif a.count == 0 then JNull
  elif e.op == "SUM" then JInt(a.total)
  elif map_height(a.ints) > 0 then JInt(extreme(a.ints, e.op == "MIN", 0))
  else JStr(extreme(a.texts, e.op == "MIN", ""))

fn substitute(e : Expr, accs : List(Acc)) : Expr =
  if agg(e.op) then literal(acc_value(at(accs, e.index), e))
  else Expr { ..e, args = map(\(a) -> substitute(a, accs), e.args) }

pub type BagGroup = BagGroup { members: Rows, accs: List(Acc) }
fn empty_group(aggs : List(Expr)) : BagGroup =
  BagGroup { members = empty_rows(), accs = map(\(_) -> empty_acc(), aggs) }

fn group_key(p : Plan, row : List(Json)) : String =
  encode(JArr(map(\(e) -> evaluate(e, row, []), p.query.groups)))

fn first_member(g : BagGroup) : (String, List(Json)) =
  match map_min(g.members) of
    Some(pair) => pair
    None => ("", [])

pub type View = View {
  plan: Plan, aggs: List(Expr), scans: List(Rows), stages: List(Stage),
  filtered: Rows, groups: Map(String, BagGroup), projected: Rows, result: Json
}

fn project_group(p : Plan, g : BagGroup) : List(List(Json)) =
  let row = snd(first_member(g))
  if truth(evaluate(substitute(p.query.having, g.accs), row, [])) then
    [map(\(s) -> evaluate(substitute(fst(s), g.accs), row, []), p.query.select)]
  else []

fn change_group(groups : Map(String, BagGroup), p : Plan, aggs : List(Expr), k : String, row : List(Json), sign : Int) : Map(String, BagGroup) =
  let key = group_key(p, row)
  let g = lookup(key, groups, empty_group(aggs))
  let members = if sign < 0 then map_delete(k, g.members) else map_insert(k, row, g.members)
  let accs = map(\(i) -> accumulate(at(g.accs, i), at(aggs, i), row, sign), range(0, length(aggs)))
  map_insert(key, BagGroup { members = members, accs = accs }, groups)

fn maintain_output(v : View, joined : Rows, delta : List(String)) : View =
  let p = v.plan
  var filtered := v.filtered
  var dirty := map_empty
  var groups := v.groups
  var projected := v.projected
  for k in sof(delta) do
    match map_lookup(k, v.filtered) of
      Some(row) =>
        if p.aggregate then
          dirty := map_insert(group_key(p, row), true, dirty)
          groups := change_group(groups, p, v.aggs, k, row, -1)
        filtered := map_delete(k, filtered)
      None => ()
    if not(p.aggregate) then projected := map_delete(k, projected)
    match map_lookup(k, joined) of
      Some(row) =>
        if truth(evaluate(p.query.predicate, row, [])) then
          filtered := map_insert(k, row, filtered)
          if p.aggregate then
            dirty := map_insert(group_key(p, row), true, dirty)
            groups := change_group(groups, p, v.aggs, k, row, 1)
          else
            projected := map_insert(k, map(\(s) -> evaluate(fst(s), row, []), p.query.select), projected)
      None => ()
  if p.aggregate then
    if length(p.query.groups) == 0 then
      dirty := map_insert("[]", true, dirty)
      if not(map_member("[]", groups)) then groups := map_insert("[]", empty_group(v.aggs), groups)
    -- Remove all previous encounter keys before installing any replacements:
    -- a moved row can become the first member of a different group.
    for item in sof(map_to_list(dirty)) do
      match map_lookup(fst(item), v.groups) of
        Some(g) => projected := map_delete(fst(first_member(g)), projected)
        None => ()
    for item in sof(map_to_list(dirty)) do
      let key = fst(item)
      let g = lookup(key, groups, empty_group(v.aggs))
      if map_height(g.members) == 0 && length(p.query.groups) > 0 then
        groups := map_delete(key, groups)
      else
        for row in sof(project_group(p, g)) do
          projected := map_insert(fst(first_member(g)), row, projected)
  let result = finish(p, map(snd, map_to_list(projected)))
  View { ..v, filtered = filtered, groups = groups, projected = projected, result = result }

pub fn create_view(plan : Plan, database : Map(String, Base)) : View =
  let prepared = prepare(plan)
  -- Bound tables retain schema only; all live data is owned by Base/scans.
  let p = Plan { ..fst(prepared), tables = map(\(t) -> Table { ..t, rows = [] }, plan.tables) }
  let scans = map(\(i) -> initial_scan(p, i, lookup(at(p.tables, i).name, database, base_table(at(p.tables, i)))), range(0, length(p.tables)))
  var rows := at(scans, 0)
  var delta := map(fst, map_to_list(rows))
  var stages := []
  var offset := length(at(p.tables, 0).columns)
  for i in srange(0, length(p.query.joins)) do
    let right = at(scans, i + 1)
    let width = length(at(p.tables, i + 1).columns)
    let next = maintain_join(empty_stage(at(p.query.joins, i), offset), empty_rows(), rows, delta, empty_rows(), right, map(fst, map_to_list(right)), at(p.query.joins, i), at(p.query.left_joins, i), width)
    stages := Cons(fst(next), stages)
    rows := fst(next).rows
    delta := snd(next)
    offset += width
  let v = View { plan = p, aggs = snd(prepared), scans = scans, stages = reverse(stages), filtered = empty_rows(), groups = map_empty, projected = empty_rows(), result = JNull }
  maintain_output(v, rows, delta)

pub fn update_view(v : View, old : Map(String, Base), new : Map(String, Base), touched : Map(String, List(Int))) : View =
  let p = v.plan
  if all(\(t) -> not(map_member(t.name, touched)), p.tables) then v
  else
    var scans := []
    var deltas := []
    for i in srange(0, length(p.tables)) do
      let t = at(p.tables, i)
      let fallback = base_table(t)
      let next = changed_scan(p, i, lookup(t.name, old, fallback), lookup(t.name, new, fallback), lookup(t.name, touched, []), at(v.scans, i))
      scans := Cons(fst(next), scans)
      deltas := Cons(snd(next), deltas)
    let ns = reverse(scans)
    let ds = reverse(deltas)
    var old_rows := at(v.scans, 0)
    var rows := at(ns, 0)
    var delta := at(ds, 0)
    var stages := []
    for i in srange(0, length(p.query.joins)) do
      let stage = at(v.stages, i)
      let next = maintain_join(stage, old_rows, rows, delta, at(v.scans, i + 1), at(ns, i + 1), at(ds, i + 1), at(p.query.joins, i), at(p.query.left_joins, i), length(at(p.tables, i + 1).columns))
      stages := Cons(fst(next), stages)
      old_rows := stage.rows
      rows := fst(next).rows
      delta := snd(next)
    maintain_output(View { ..v, scans = ns, stages = reverse(stages) }, rows, delta)

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">=", "IS"]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node(w, [expression(3)])
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif w == "NULL" then
      literal(JNull)
    elif w == "COALESCE" then
      expect("(")
      let args = arguments()
      demand(length(args) >= 2, "PARSE_ERROR")
      expect(")")
      node(w, args)
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  let p = precedence(op)
  if p < minimum then
    left
  else
    demand(not(p == 4 && compared), "PARSE_ERROR")
    let ignored = pop()
    let next =
      if op == "IS" then
        let negated = accept("NOT")
        expect("NULL")
        node(if negated then "IS NOT NULL" else "IS NULL", [left])
      else
        node(op, [left, expression(p + 1)])
    binary(next, minimum, compared || p == 4)

fn arguments() : List(Expr) =
  let e = expression(1)
  Cons(e, if accept(",") then arguments() else [])

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, (Bool, Bool))) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let first =
    if accept("NULLS") then
      if accept("FIRST") then
        true
      else
        expect("LAST")
        false
    else
      desc
  Cons((n, (desc, first)), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  ls : List(Bool)
) : (List((String, String)), (List(Expr), List(Bool))) =
  if elem(peek(), ["INNER", "JOIN", "LEFT"]) then
    let left = accept("LEFT")
    if left then
      let ignored = accept("OUTER")
      ()
    else
      let ignored = accept("INNER")
      ()
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(ls, [left]))
  else
    (ss, (js, ls))

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, (js, ls)) = join_sources([source()], [], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    left_joins = ls,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
    distinct = distinct,
    limit = lim,
    offset = off
  }

pub fn parse_sql(s : String) : Query = eval_state(lex(s, 0), query)

-- One request, one response. Domain effects abort the complete query batch.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Commands (commands, has_field)
import Data.List (..)
import Data.Foldable (length)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  let mode = has_field(input, "commands")
  fields(input, if mode then ["database", "commands"] else ["database", "queries"])
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  if mode then
    commands(database, arr(getfield(input, "commands")))
  else
    let queries = arr(getfield(input, "queries"))
    for q in sof(queries) do
      validate_query(q)
    let results = map(
        \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
        queries,
      )
    JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn error_response(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn decode_work(line : String) : Json =
  match decode_lossy(line) of
    Ok(request) => work(request)
    Err(_) => error_response("INVALID_INPUT")

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))

